import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0067 — Sito della documentazione su GitHub Pages, pubblicato da un workflow dedicato","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0067-sito-documentazione-github-pages.md","filePath":"adr/0067-sito-documentazione-github-pages.md"}'),c={name:"adr/0067-sito-documentazione-github-pages.md"};function n(d,e,r,s,l,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0067-—-sito-della-documentazione-su-github-pages-pubblicato-da-un-workflow-dedicato" tabindex="-1">ADR-0067 — Sito della documentazione su GitHub Pages, pubblicato da un workflow dedicato <a class="header-anchor" href="#adr-0067-—-sito-della-documentazione-su-github-pages-pubblicato-da-un-workflow-dedicato" aria-label="Permalink to &quot;ADR-0067 — Sito della documentazione su GitHub Pages, pubblicato da un workflow dedicato&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>proposta</td></tr><tr><td><strong>Data</strong></td><td>2026-11-23</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§6 (Branching/verifiche); ADR-0036 (verifiche locali senza CI), ADR-0031 (pipeline di rilascio), ADR-0032 (Task)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì: la riga «Branching/verifiche» e la voce ADR-0031 dell&#39;Appendice C dicono che <code>release.yml</code> è l&#39;unico workflow → richiede l&#39;aggiornamento di <code>Specifications.md</code> da parte dell&#39;owner</td></tr><tr><td><strong>Superfici</strong></td><td>nessuna superficie del prodotto: solo documentazione e repository</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p><code>docs/</code> contiene circa 140 documenti in Markdown (guide utente e admin, architettura, ADR, QA, rilascio, sicurezza), leggibili solo nel repository. Il proprietario vuole un sito statico pubblicato su GitHub Pages, generato da <code>docs/</code> in <code>docs_html/</code>, e aggiornato automaticamente.</p><p>GitHub Pages, quando pubblica da un branch, serve solo la radice o la cartella <code>/docs</code>: una cartella <code>docs_html/</code> si pubblica caricandola su un branch dedicato oppure con un workflow. ADR-0036 ha stabilito che non c&#39;è un servizio di CI e che <code>release.yml</code> è l&#39;unico workflow.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><strong>Generatore: VitePress 1.6</strong> (dipendenza di sviluppo della radice del workspace Yarn), configurazione in <code>docs/.vitepress/config.mjs</code>, output in <code>docs_html/</code> (ignorata da git, Prettier ed ESLint), base path <code>/Clarae/</code> (sito di progetto; <code>DOCS_BASE</code> la cambia). La barra laterale segue le sezioni di <code>docs/index.md</code>; <code>README.md</code> diventa l&#39;indice della sua cartella; i link relativi a file che non sono pagine (<code>Specifications.md</code>, sorgenti, <code>api/</code>) puntano al file su GitHub; il codice inline è protetto dall&#39;interpolazione di Vue; <code>.nojekyll</code> nell&#39;output.</li><li><strong>Pubblicazione sul branch <code>gh-pages</code></strong> con <code>scripts/docs-publish.sh</code>: un commit costruito con un indice temporaneo (niente checkout, worktree o branch locale) sopra la punta remota di <code>gh-pages</code>, che conserva la storia; push in fast-forward; nessun commit se il sito non è cambiato. <code>task docs-publish</code> costruisce e pubblica in locale (<code>DOCS_REMOTE</code>, <code>DOCS_BRANCH</code>, <code>DOCS_DRY_RUN=1</code>).</li><li><strong>Workflow <code>.github/workflows/docs.yml</code></strong>, eccezione dichiarata ad ADR-0036: su ogni push su <code>main</code> che tocca <code>docs/</code>, gli asset del marchio, le dipendenze o lo script stesso (e a mano con <code>workflow_dispatch</code>) esegue <code>yarn install --immutable</code>, <code>yarn docs:build</code> e lo script di pubblicazione, come <code>github-actions[bot]</code>. Permesso <code>contents: write</code> solo per il job, azioni fissate a uno SHA come in <code>release.yml</code> (<code>deploy/PINS.md</code>), una pubblicazione alla volta senza cancellazioni. <strong>Non esegue controlli</strong>: <code>task ci</code> resta il cancello prima di un merge.</li><li><strong>Configurazione una tantum del repository</strong> (a cura dell&#39;owner): Settings → Pages → <em>Deploy from a branch</em> → <code>gh-pages</code>, <code>/ (root)</code>.</li></ol><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong><code>actions/upload-pages-artifact</code> + <code>actions/deploy-pages</code></strong> (Pages da workflow, senza branch): niente branch con file generati, ma il sito si può pubblicare solo dal workflow, mentre il proprietario vuole anche la pubblicazione locale su <code>gh-pages</code>. Scartata per ora; resta un passaggio semplice (stesso build, cambia solo l&#39;ultimo step).</li><li><strong>Solo pubblicazione locale, senza workflow:</strong> rispetta alla lettera ADR-0036, ma il sito resterebbe indietro rispetto a <code>main</code>. Scartata su richiesta del proprietario.</li><li><strong>MkDocs Material:</strong> buon supporto al Markdown puro, ma porta Python e pip nella toolchain (Go + Node). Scartata.</li><li><strong>Committare <code>docs_html/</code> su <code>main</code>:</strong> GitHub Pages non la servirebbe (solo radice o <code>/docs</code>) e gonfierebbe la storia di <code>main</code>. Scartata.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li><strong>Positive:</strong> documentazione navigabile e cercabile, aggiornata a ogni push su <code>main</code> senza passi manuali; nessun segreto (basta il <code>GITHUB_TOKEN</code>).</li><li><strong>Negative:</strong> un secondo workflow da mantenere (pin delle azioni insieme a quelli di <code>release.yml</code>); un branch <code>gh-pages</code> con soli file generati, che cresce di un commit per pubblicazione. Le pagine sono template Vue: un tag HTML non chiuso nel testo di un documento (fuori dal codice) rompe il build del sito, che va quindi provato con <code>task docs-build</code> quando si scrivono documenti.</li><li><strong>Da fare:</strong> l&#39;owner aggiorna <code>Specifications.md</code> (§6 e Appendice C) e abilita Pages sul branch <code>gh-pages</code>. Se il repository è privato, GitHub Pages richiede un piano a pagamento.</li></ul>',11)])])}const b=o(c,[["render",n]]);export{g as __pageData,b as default};
